\begin{tikzpicture}[x=1cm,y=1cm,font=\fontsize{10}{12}\selectfont]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\path[use as bounding box] (-2.8,-2.8) rectangle (2.9,2.9);
\draw[black,line width=0.5pt,->] (-2.6,0)--(2.6,0) node[right] {$x$};
\draw[black,line width=0.5pt,->] (0,-2.6)--(0,2.6) node[above] {$y$};
\draw[black,line width=0.4pt,dashed] (1,0)--(1,1)--(0,1);
\draw[black,line width=0.4pt,dashed] (-1,0)--(-1,-1)--(0,-1);
\foreach \v in {-1,1}{\draw[black,line width=0.4pt] (\v,-0.05)--(\v,0.05);\node[below,font=\fontsize{8.5}{10}\selectfont] at (\v,-0.06) {\special{dvisvgm:raw <g data-graph-text="tick">}$\v$\special{dvisvgm:raw </g>}};\draw[black,line width=0.4pt] (-0.05,\v)--(0.05,\v);\node[left,font=\fontsize{8.5}{10}\selectfont] at (-0.06,\v) {\special{dvisvgm:raw <g data-graph-text="tick">}$\v$\special{dvisvgm:raw </g>}};}
\draw[black,line width=0.8pt,<->,domain=0.4:2.5,samples=90] plot (\x,{1/\x});
\draw[black,line width=0.8pt,<->,domain=-2.5:-0.4,samples=90] plot (\x,{1/\x});
\node[right] at (0.55,2.1) {$y=\frac1x$};
\end{tikzpicture}

